CREATE TABLE users (id UUID PRIMARY KEY, name VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, created_at TIMESTAMP NOT NULL);
CREATE TABLE banks (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id), name VARCHAR(255) NOT NULL, code VARCHAR(50), type VARCHAR(30) NOT NULL);
CREATE TABLE accounts (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id), bank_id UUID NOT NULL REFERENCES banks(id), name VARCHAR(255) NOT NULL, type VARCHAR(30) NOT NULL);
CREATE TABLE categories (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id), name VARCHAR(255) NOT NULL, color VARCHAR(7) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(user_id, name));
CREATE TABLE credit_cards (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id), bank_id UUID NOT NULL REFERENCES banks(id), name VARCHAR(255) NOT NULL, last_four_digits VARCHAR(4) NOT NULL, limit_amount NUMERIC(19,2) NOT NULL, closing_day SMALLINT NOT NULL CHECK(closing_day BETWEEN 1 AND 31), due_day SMALLINT NOT NULL CHECK(due_day BETWEEN 1 AND 31), active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE card_invoices (id UUID PRIMARY KEY, credit_card_id UUID NOT NULL REFERENCES credit_cards(id), reference_month VARCHAR(7) NOT NULL, closing_date DATE NOT NULL, due_date DATE NOT NULL, status VARCHAR(20) NOT NULL, UNIQUE(credit_card_id, reference_month));
CREATE TABLE subscriptions (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id), category_id UUID NOT NULL REFERENCES categories(id), credit_card_id UUID REFERENCES credit_cards(id), account_id UUID REFERENCES accounts(id), name VARCHAR(255) NOT NULL, amount NUMERIC(19,2) NOT NULL CHECK(amount > 0), frequency VARCHAR(20) NOT NULL, charge_day SMALLINT NOT NULL CHECK(charge_day BETWEEN 1 AND 31), active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE expenses (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id), category_id UUID NOT NULL REFERENCES categories(id), account_id UUID REFERENCES accounts(id), credit_card_id UUID REFERENCES credit_cards(id), subscription_id UUID REFERENCES subscriptions(id), description VARCHAR(500) NOT NULL, merchant VARCHAR(255), purchase_date DATE NOT NULL, total_amount NUMERIC(19,2) NOT NULL CHECK(total_amount > 0), payment_method VARCHAR(30) NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE expense_installments (id UUID PRIMARY KEY, expense_id UUID NOT NULL REFERENCES expenses(id) ON DELETE CASCADE, invoice_id UUID REFERENCES card_invoices(id), number INTEGER NOT NULL, total INTEGER NOT NULL, amount NUMERIC(19,2) NOT NULL CHECK(amount > 0), due_date DATE NOT NULL, status VARCHAR(20) NOT NULL, CHECK(number BETWEEN 1 AND total));
CREATE INDEX idx_expenses_user ON expenses(user_id); CREATE INDEX idx_installments_due ON expense_installments(due_date);
